class CheckIfFileOrFolderExists(API_base):
    """
    This API checks if a string or folder exists in the specified storage.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_path", "p_versionId", "p_storageName"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_path = params.get('p_path', None)
        if p_path is None:
            return self.handle_error(f"Required parameter 'p_path' is missing", 400)
        is_valid, error = self.validate_type(p_path, 'p_path', str)
        if not is_valid:
            return error
        
        p_versionId = params.get('p_versionId', "")
        if p_versionId is not None:
            is_valid, error = self.validate_type(p_versionId, 'p_versionId', str)
            if not is_valid:
                return error
        
        p_storageName = params.get('p_storageName', "First Storage")
        if p_storageName is not None:
            is_valid, error = self.validate_type(p_storageName, 'p_storageName', str)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "CheckIfFileOrFolderExists",
                "p_path": p_path,
                "p_versionId": p_versionId,
                "p_storageName": p_storageName
            }
        }

